<?php
namespace App\Http\Requests\ProfileUpdates;
use Illuminate\Foundation\Http\FormRequest;use Illuminate\Validation\Rule;use Illuminate\Validation\Validator;
class ListProfileUpdateRequestsRequest extends FormRequest{public function authorize():bool{return true;}public function rules():array{return ['status'=>['sometimes',Rule::in(['pending','approved','rejected','withdrawn'])],'member_search'=>['sometimes','string','max:100'],'changed_field'=>['sometimes',Rule::in(\App\Models\ProfileUpdateRequestChange::ALLOWED_FIELDS)],'date_from'=>['sometimes','date_format:Y-m-d'],'date_to'=>['sometimes','date_format:Y-m-d','after_or_equal:date_from'],'page'=>['sometimes','integer','min:1'],'per_page'=>['sometimes','integer','min:1','max:100']];}public function after():array{return[function(Validator $v):void{$unknown=array_diff(array_keys($this->query()),array_keys($this->rules()));if($unknown)$v->errors()->add('filters','Unknown filters: '.implode(', ',$unknown));if($this->date('date_from')&&$this->date('date_to')&&$this->date('date_from')->diffInDays($this->date('date_to'))>366)$v->errors()->add('date_to','Date range may not exceed 366 days.');}];}}
